/* Spring 2027 review questions (added Nov 14, 2026). Same format as review.js; merged by BioLab.addReview.
   "verify" is read only by the test script. */
BioLab.addReview({
calorimetry:{
  apNote:'Released questions from College Board. Calorimetry questions almost always hinge on q = mcΔT and getting the sign of ΔH right.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'beach',kind:'real',lvl:'bio',
    q:'On a sunny afternoon at the lake, the sand burns your feet but the water still feels cool. Both got the same sunshine. Why?',
    choices:['Water has a much higher specific heat, so the same energy warms it far less','Sand is darker, so it is the only one that absorbs sunlight','Water is always colder than air','Sand has a higher specific heat than water'],correct:0,
    steps:['Specific heat is the energy it takes to warm 1 g by 1 °C. Water: 4.184 J/g·°C. Dry sand: about 0.8.','The same sunshine on the same mass warms the sand about five times as much.','The metal block in the lab works the same way: it changes temperature far more than the water it sits in.'],
    lab:{set:{mode:'metal',metal:'cu',mMetal:50},look:'Compare how far the metal’s temperature falls with how far the water’s rises.'}},
  {id:'alvspb',kind:'test',lvl:'bio',
    q:'You drop 50 g of aluminum at 100 °C into 100 g of water at 20 °C. Then you repeat it with 50 g of lead. Which one warms the water more?',
    choices:['Aluminum, because it has a higher specific heat and holds more heat','Lead, because it is heavier for its size','Both the same, because the masses are the same','Neither warms the water'],correct:0,
    steps:['Aluminum’s specific heat is 0.897 J/g·°C; lead’s is 0.129. At the same mass and temperature, the aluminum holds about 7 times as much heat.','The aluminum brings the water to about 27.7 °C. The lead brings it only to about 21.2 °C.','Same mass does not mean same heat. What matters is mass × specific heat.'],
    lab:{set:{mode:'metal',metal:'al',mMetal:50},look:'Let it reach equilibrium and read the water temperature. Then switch the metal to lead and run it again.'},verify:[['Tw',27.7,.3]],wait:150},
  {id:'qcopper',kind:'test',lvl:'honors',
    q:'50.0 g of copper at 100.0 °C goes into 100.0 g of water at 20.0 °C. The water ends at 23.5 °C. How much heat did the water gain? (c = 4.184 J/g·°C)',
    num:{ans:1470,tol:30,unit:'J'},
    steps:['q = m·c·ΔT for the water: ΔT = 23.5 − 20.0 = 3.5 °C.','q = 100.0 g × 4.184 J/g·°C × 3.5 °C ≈ 1470 J.','The copper lost the same 1470 J. Its temperature fell about 76.5 °C because its heat capacity (50 × 0.385 = 19.3 J/°C) is so small.'],
    lab:{set:{mode:'metal',metal:'cu',mMetal:50},look:'Read <b>Heat gained by water</b> once the temperatures match.'},verify:[['qw',1472,15]],wait:150},
  {id:'unknownb',kind:'test',lvl:'honors',
    q:'Unknown metal B (50.0 g, 100.0 °C) goes into 100.0 g of water at 20.0 °C. The water ends at 21.2 °C. Which metal is it?',
    choices:['Aluminum (0.897 J/g·°C)','Iron (0.449 J/g·°C)','Copper (0.385 J/g·°C)','Lead (0.129 J/g·°C)'],correct:3,
    steps:['q_water = 100.0 × 4.184 × 1.2 ≈ 500 J.','The metal changed by 21.2 − 100.0 = −78.8 °C.','c = 500 ÷ (50.0 × 78.8) ≈ 0.13 J/g·°C: lead. With a rise this small, reading the thermometer to 0.1 °C matters.'],
    lab:{set:{mode:'metal',metal:'ub',mMetal:50},look:'Wait for equilibrium, then read <b>Closest metal in the table</b>.'},verify:[['match','Lead']],wait:150},
  {id:'puffs',kind:'real',lvl:'bio',
    q:'Your class burns cheese puffs under soda cans and gets about 1.6 Calories per gram. The bag says 5.7. What went wrong?',
    choices:['Most of the flame’s heat went into the air instead of the water','The bag is wrong','Water absorbs too much heat','Burning creates extra Calories'],correct:0,
    steps:['q = mcΔT only counts heat that reaches the water.','In an open can only about 28% of the flame’s heat does. The rest warms the air, the can and the holder.','So a soda-can calorimeter always reads low. A bomb calorimeter, which traps the heat, gets close to the label.'],
    lab:{set:{mode:'food',snack:'puff',mSnack:1.2},look:'Let it burn out, then compare <b>Your result</b> with the <b>Nutrition label value</b>.'},verify:[['cpg',1.6,.12]],wait:150},
  {id:'shield',kind:'test',lvl:'honors',
    q:'You wrap a foil draft shield around the can and burn another 1.2 g cheese puff. About what percent of the label value do you get now?',
    choices:['About 28%, the same as before','About 45%','About 100%','More than 100%'],correct:1,
    steps:['The shield keeps more of the hot gas around the can, so more heat reaches the water.','In the model, about 45% of the flame’s heat now reaches the water: about 2.6 Cal/g.','Better, but still far below the label. Heat loss can only make the result low, never high.'],
    lab:{set:{mode:'food',snack:'puff',mSnack:1.2,setup:'shield'},look:'Read <b>Your result as a percent of the label</b>.'},verify:[['pct',45,3]],wait:150},
  {id:'bombpeanut',kind:'ap',lvl:'ap',
    q:'A 1.20 g peanut (5.85 Cal/g) burns completely in a bomb calorimeter with C_cal = 10.00 kJ/°C. By how much does the water temperature rise?',
    num:{ans:2.94,tol:.04,unit:'°C'},
    steps:['Energy released: 1.20 g × 5.85 Cal/g × 4.184 kJ/Cal = 29.4 kJ.','ΔT = q ÷ C_cal = 29.4 kJ ÷ 10.00 kJ/°C = 2.94 °C.','The rise is small because the bomb, bucket and 2 kg of water have a huge heat capacity. That is why bomb thermometers read to 0.001 °C.'],
    lab:{set:{mode:'bomb',snack:'peanut',mSnack:1.2},look:'Wait for the water to level off and read <b>Temperature rise, ΔT</b>.'},verify:[['dTB',2.94,.02]],wait:90},
  {id:'signs',kind:'ap',lvl:'ap',
    q:'Hot iron goes into cool water in a coffee-cup calorimeter. Which signs are right?',
    choices:['q_water > 0 and q_iron < 0','q_water < 0 and q_iron > 0','Both positive','Both negative'],correct:0,
    steps:['q is positive for whatever gains heat and negative for whatever loses it.','The water warms (q_water > 0) and the iron cools (q_iron < 0).','In a perfect calorimeter q_iron = −q_water. For a reaction in water, ΔH has the sign of q_reaction = −q_water.']}
  ]},
coldpack:{
  apNote:'Released questions from College Board. Heat-of-solution questions combine q = mcΔT, moles and the sign of ΔH.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'firstaid',kind:'real',lvl:'bio',
    q:'At a soccer game you squeeze an instant cold pack. A water pouch breaks and the salt inside dissolves. Where does the “cold” come from?',
    choices:['Dissolving the salt absorbs heat from the water, and the water then absorbs heat from your ankle','The salt was frozen in the factory','The pack releases cold energy','The plastic reacts with the air'],correct:0,
    steps:['Many cold packs use ammonium nitrate. Pulling its solid apart takes more energy than the water gives back when it surrounds the ions.','That energy comes out of the water, so the water cools. It is an endothermic process.','Nothing adds “cold.” Heat flows from your warm ankle into the cooler pack.'],
    lab:{set:{mode:'pack',salt:'nh4no3',mass:10,water:100},look:'Watch the thermometer as the salt dissolves.'},verify:[['dT',-7,.6]]},
  {id:'warmer',kind:'test',lvl:'bio',
    q:'You want a pack that gets warm. Which salt should go in it?',
    choices:['Calcium chloride (CaCl₂)','Ammonium nitrate (NH₄NO₃)','Ammonium chloride (NH₄Cl)','Sodium chloride (NaCl)'],correct:0,
    steps:['Calcium chloride dissolving is exothermic: 10 g warms 100 mL of water about 16 °C.','Ammonium nitrate and ammonium chloride cool the water. Table salt barely changes it.','Calcium chloride is also the salt spread on icy sidewalks: it releases heat as it dissolves.'],
    lab:{set:{mode:'pack',salt:'cacl2',mass:10,water:100},look:'Read <b>This process is</b> and the temperature change.'},verifyAbove:[['dT',12]]},
  {id:'double',kind:'test',lvl:'bio',
    q:'10 g of ammonium nitrate cools 100 mL of water by about 7 °C. What about 20 g in the same water?',
    choices:['It cools by about 13 °C, close to double','It cools by about 7 °C again','It cools by about 3.5 °C','It warms the water instead'],correct:0,
    steps:['Twice the salt absorbs twice the heat.','The extra 10 g also adds a little mass to the solution, so the drop is a bit less than double: about 12.8 °C.','The amount of salt is what a pack designer controls.'],
    lab:{set:{mode:'pack',salt:'nh4no3',mass:20,water:100},look:'Read the temperature change, ΔT.'},verify:[['dT',-12.8,.6]]},
  {id:'design5',kind:'real',lvl:'honors',
    q:'A cold pack must reach 5 °C from 22 °C using 100 mL of water and ammonium nitrate (ΔH_soln = +25.7 kJ/mol, 80.04 g/mol). About how much salt do you need?',
    choices:['About 10 g','About 28 g','About 60 g','About 100 g'],correct:1,
    steps:['ΔT = −17 °C. The heat taken from the solution is (100 + m) g × 4.18 × 17.','The salt absorbs (m ÷ 80.04) × 25 700 J. Set them equal: 321m = 7106 + 71m, so m ≈ 28 g.','28.5 g in the model gets the solution to about 5.0 °C. Real packs use about this ratio.'],
    lab:{set:{mode:'pack',salt:'nh4no3',mass:28.5,water:100,target:'cold'},look:'Read the temperature and <b>Design check</b>.'},verify:[['T',5,.6]]},
  {id:'cacl2dh',kind:'test',lvl:'honors',
    q:'5.00 g of CaCl₂ (110.98 g/mol) dissolves in 100 mL of water and warms it by 8.35 °C. Mass of solution: 105.0 g. What is ΔH_soln? (c = 4.18 J/g·°C)',
    num:{ans:-81.3,tol:1.5,unit:'kJ/mol'},
    steps:['q_solution = 105.0 × 4.18 × 8.35 = 3665 J, so q_rxn = −3665 J (the reaction released it).','n = 5.00 ÷ 110.98 = 0.04505 mol.','ΔH_soln = −3.665 kJ ÷ 0.04505 mol = −81.3 kJ/mol. Negative means exothermic.'],
    lab:{set:{mode:'pack',salt:'cacl2',mass:5,water:100},look:'Read <b>ΔH_soln from your data</b>.'},verify:[['dH',-81.3,1.2]]},
  {id:'neut',kind:'test',lvl:'honors',
    q:'50 mL of 1.0 M HCl and 50 mL of 1.0 M NaOH warm by 6.8 °C. What is ΔH_neut per mole of water formed? (100 g of solution, c = 4.18 J/g·°C)',
    num:{ans:-57,tol:1.5,unit:'kJ/mol'},
    steps:['q_solution = 100 g × 4.18 × 6.8 = 2842 J, so q_rxn = −2.84 kJ.','Water formed = 0.050 L × 1.0 M = 0.050 mol.','ΔH_neut = −2.84 ÷ 0.050 ≈ −57 kJ/mol. Every strong acid with a strong base gives about this value.'],
    lab:{set:{mode:'neut',vA:50,vB:50,cA:1,cB:1},look:'Read <b>ΔH_neut from your data</b>.'},verify:[['dHn',-57,1.5]]},
  {id:'whycold',kind:'ap',lvl:'ap',
    q:'Dissolving NH₄NO₃ is endothermic. In terms of the two energy steps, why?',
    choices:['The energy to separate the ions from the crystal is larger than the energy released when water surrounds them','Hydration absorbs energy and breaking the lattice releases it','Both steps release energy','The water molecules break apart'],correct:0,
    steps:['Breaking the crystal apart always costs energy (lattice energy in).','Water surrounding the ions always releases energy (hydration energy out).','For NH₄NO₃ the cost is larger, so ΔH_soln is positive (+25.7 kJ/mol). For CaCl₂ the small, highly charged Ca²⁺ makes hydration win.'],
    lab:{set:{mode:'pack',salt:'nh4no3'},look:'Compare the “in” and “out” arrows on the energy diagram.'}},
  {id:'nacl',kind:'ap',lvl:'ap',
    q:'NaCl has ΔH_soln = +3.9 kJ/mol (58.44 g/mol). 10.0 g dissolves in 100 mL of water (110 g of solution). What is ΔT?',
    num:{ans:-1.45,tol:.12,unit:'°C'},
    steps:['n = 10.0 ÷ 58.44 = 0.171 mol.','q_rxn = 0.171 × 3900 = 667 J absorbed, so q_solution = −667 J.','ΔT = −667 ÷ (110 × 4.18) = −1.45 °C. The two energy steps nearly cancel for table salt.'],
    lab:{set:{mode:'pack',salt:'nacl',mass:10,water:100},look:'Read the temperature change, ΔT.'},verify:[['dT',-1.45,.12]]}
  ]},
enthalpy:{
  apNote:'Released questions from College Board. ΔH questions use bond enthalpies, Hess’s law or ΔH°f tables, and the sign tells you which way heat flows.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'stove',kind:'real',lvl:'bio',
    q:'A gas stove needs a spark to light, but then it keeps burning on its own. Why?',
    choices:['The spark gets the first bonds breaking; forming CO₂ and H₂O then releases more energy than breaking the old bonds took, and that keeps it going','The spark supplies all the energy of the flame','The flame runs on the electricity in the spark','Methane bonds release energy when they break'],correct:0,
    steps:['Breaking bonds always costs energy. The spark pays that first cost.','Forming the strong bonds in CO₂ and H₂O releases more energy than was spent, about 802 kJ per mole of methane.','Some of that released energy breaks the next molecules’ bonds, so the flame keeps itself going.'],
    lab:{set:{mode:'bonds',rxn:'ch4'},act:'f',look:'Compare the red “Energy in” bar with the blue “Energy out” bar.'}},
  {id:'ammonia',kind:'test',lvl:'bio',
    q:'Making ammonia, N₂ + 3H₂ → 2NH₃, breaks 1 N≡N and 3 H–H bonds and forms 6 N–H bonds. Is it endothermic or exothermic?',
    choices:['Exothermic: forming the N–H bonds releases more than breaking took','Endothermic: breaking the triple bond takes more than forming releases','Neither'],correct:0,
    steps:['Energy in: 945 + 3 × 436 = 2253 kJ.','Energy out: 6 × 391 = 2346 kJ.','Out is bigger, so about 93 kJ is released: exothermic. Fertilizer factories run this reaction around the clock.'],
    lab:{set:{mode:'bonds',rxn:'nh3'},act:'f',look:'Read <b>This reaction is</b>.'},verify:[['kind','exo']]},
  {id:'ch4est',kind:'test',lvl:'honors',
    q:'Estimate ΔH for CH₄ + 2O₂ → CO₂ + 2H₂O(g). Bond enthalpies (kJ/mol): C–H 413, O=O 498, C=O 799, O–H 463.',
    num:{ans:-802,tol:5,unit:'kJ'},
    steps:['Broken: 4 C–H + 2 O=O = 4(413) + 2(498) = 2648 kJ.','Formed: 2 C=O + 4 O–H = 2(799) + 4(463) = 3450 kJ.','ΔH ≈ broken − formed = 2648 − 3450 = −802 kJ.'],
    lab:{set:{mode:'bonds',rxn:'ch4'},act:'f',look:'Read <b>ΔH estimate from bond energies</b>.'},verify:[['est',-802,2]]},
  {id:'lightning',kind:'real',lvl:'honors',
    q:'Lightning and hot car engines turn N₂ and O₂ into NO, a smog gas: N₂ + O₂ → 2NO. Bond enthalpies: N≡N 945, O=O 498, N–O (in NO) 631. What is ΔH?',
    num:{ans:181,tol:4,unit:'kJ'},
    steps:['Broken: 945 + 498 = 1443 kJ.','Formed: 2 × 631 = 1262 kJ.','ΔH ≈ 1443 − 1262 = +181 kJ: endothermic. That is why NO forms only where it is very hot, like lightning or an engine cylinder.'],
    lab:{set:{mode:'bonds',rxn:'no'},act:'f',look:'Read <b>ΔH estimate from bond energies</b>.'},verify:[['est',181,2]]},
  {id:'flip3',kind:'test',lvl:'honors',
    q:'A → 2B has ΔH = −50 kJ. What is ΔH for 6B → 3A?',
    num:{ans:150,tol:.5,unit:'kJ'},
    steps:['Flip the equation: 2B → A has ΔH = +50 kJ.','Multiply by 3: 6B → 3A has ΔH = 3 × (+50) = +150 kJ.','Flipping changes the sign; scaling multiplies the value. That is all of Hess’s law.']},
  {id:'propane',kind:'ap',lvl:'ap',
    q:'Use ΔH°f (kJ/mol): C₃H₈(g) −103.8, CO₂(g) −393.5, H₂O(l) −285.8. Find ΔH° for C₃H₈ + 5O₂ → 3CO₂ + 4H₂O(l).',
    num:{ans:-2219.9,tol:3,unit:'kJ'},
    steps:['Products: 3(−393.5) + 4(−285.8) = −1180.5 − 1143.2 = −2323.7 kJ.','Reactants: −103.8 + 5(0) = −103.8 kJ. O₂ is an element in its standard state.','ΔH° = −2323.7 − (−103.8) = −2219.9 kJ. A 20 lb grill tank holds about 9.1 kg of propane, which is about 200 mol, or about 460 000 kJ.'],
    lab:{set:{mode:'form',fr:'c3h8',ws:'l'},look:'Read <b>ΔH°rxn</b>.'},verify:[['dHr',-2219.9,1]]},
  {id:'thermite',kind:'ap',lvl:'ap',
    q:'Railroad crews weld rails with thermite: 2Al + Fe₂O₃ → Al₂O₃ + 2Fe. ΔH°f: Fe₂O₃ −824.2, Al₂O₃ −1675.7 kJ/mol. What is ΔH°?',
    num:{ans:-851.5,tol:3,unit:'kJ'},
    steps:['Products: −1675.7 + 2(0) = −1675.7 kJ.','Reactants: 2(0) + (−824.2) = −824.2 kJ.','ΔH° = −1675.7 − (−824.2) = −851.5 kJ. That much heat in a small mass melts the iron, which flows into the gap between rails.'],
    lab:{set:{mode:'form',fr:'thermite'},look:'Read <b>ΔH°rxn</b>.'},verify:[['dHr',-851.5,1]]},
  {id:'average',kind:'ap',lvl:'ap',
    q:'Bond enthalpies estimate ΔH for burning methane at −802 kJ; the ΔH°f table gives −802.3 kJ. For many reactions the two differ more. Why?',
    choices:['Bond enthalpies are averages over many molecules and assume everything is a gas','ΔH°f tables are less accurate','Bond energies include the heat of the spark','The two methods measure different reactions'],correct:0,
    steps:['A C–H bond in methane is not exactly the same strength as one in ethanol. Tables give an average.','Bond enthalpies also apply only to gases, so they miss the heat of condensing or melting.','Use ΔH°f data when you have it; use bond enthalpies for a quick estimate.']}
  ]},
equilibrium:{
  apNote:'Released questions from College Board. Equilibrium questions ask you to compare Q with K and to explain shifts at the particle level.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'icetube',kind:'test',lvl:'bio',
    q:'A sealed tube of brown NO₂ and colorless N₂O₄ goes into ice water. What happens to the color?',
    choices:['It gets paler, because more NO₂ joins into colorless N₂O₄','It gets darker brown','It stays the same'],correct:0,
    steps:['Splitting N₂O₄ into NO₂ absorbs heat.','Cooling takes heat away, so the reaction shifts toward the side that releases heat: back to N₂O₄.','Fewer brown NO₂ molecules means a paler tube.'],
    lab:{set:{sys:'no2',Tg:0},look:'Watch the tube color and read [NO₂].'}},
  {id:'remove',kind:'real',lvl:'bio',
    q:'Fertilizer plants keep cooling the gas so ammonia condenses into a liquid and drains away. Why does removing the product help?',
    choices:['The reaction shifts forward to replace what was removed, so more ammonia forms','Removing product stops the reaction','It lowers K','It makes the catalyst work'],correct:0,
    steps:['At equilibrium, forward and reverse reactions run at the same rate.','Taking product away slows the reverse reaction, so the forward reaction wins for a while.','The mixture shifts toward products to replace some of what was removed. That is Le Châtelier’s principle.'],
    lab:{set:{sys:'no2',Tg:25},act:'remP',look:'Watch the product concentration drop, then climb partway back.'}},
  {id:'squeeze',kind:'test',lvl:'honors',
    q:'N₂ + 3H₂ ⇌ 2NH₃ is at equilibrium. You squeeze the container to half its volume. What happens to the amount of NH₃?',
    choices:['It increases, because the right side has fewer gas molecules','It decreases','It stays the same'],correct:0,
    steps:['The left side has 4 gas molecules (1 N₂ + 3 H₂); the right has 2.','Squeezing raises the pressure, and shifting right lowers it by making fewer molecules.','That is why the Haber process runs at high pressure, around 200 atm.'],
    lab:{set:{sys:'haber',Th:450,V:0.5},look:'Read <b>NH₃ in the gas mix</b>, then change the volume back to 1.0 L and compare.'}},
  {id:'qk',kind:'test',lvl:'honors',
    q:'For N₂O₄ ⇌ 2NO₂ at 25 °C, K = 0.0046. A flask has [N₂O₄] = 0.040 M and [NO₂] = 0.0050 M. Which way does it shift?',
    choices:['Right, toward NO₂','Left, toward N₂O₄','It is already at equilibrium'],correct:0,
    steps:['Q = [NO₂]² ÷ [N₂O₄] = (0.0050)² ÷ 0.040 = 0.000625.','Q is smaller than K = 0.0046, so there is too little product.','The forward reaction runs until Q rises to K: more NO₂ forms.']},
  {id:'silver',kind:'test',lvl:'honors',
    q:'Blue cobalt chloride solution: Co(H₂O)₆²⁺ (pink) + 4Cl⁻ ⇌ CoCl₄²⁻ (blue). You add AgNO₃, which removes Cl⁻ as solid AgCl. The color turns…',
    choices:['pinker','bluer','colorless'],correct:0,
    steps:['Removing Cl⁻ takes away a reactant.','The reaction shifts left to replace some of it, back toward pink Co(H₂O)₆²⁺.','You also see white AgCl solid form.'],
    lab:{set:{sys:'co',Tg:25},act:'ag',look:'Watch the color and read [Cl⁻].'}},
  {id:'kexpr',kind:'ap',lvl:'ap',
    q:'Which is the K expression for N₂(g) + 3H₂(g) ⇌ 2NH₃(g)?',
    choices:['[NH₃]² ÷ ([N₂][H₂]³)','[N₂][H₂]³ ÷ [NH₃]²','2[NH₃] ÷ ([N₂] + 3[H₂])','[NH₃] ÷ ([N₂][H₂])'],correct:0,
    steps:['Products over reactants.','Each concentration is raised to its coefficient from the balanced equation.','So K = [NH₃]² ÷ ([N₂][H₂]³).']},
  {id:'kcalc',kind:'ap',lvl:'ap',
    q:'At 25 °C an equilibrium mixture has [N₂O₄] = 0.043 M and [NO₂] = 0.014 M. What is K?',
    num:{ans:.0046,tol:.0002},
    steps:['K = [NO₂]² ÷ [N₂O₄].','(0.014)² = 0.000196.','0.000196 ÷ 0.043 = 0.0046. K is small, so at 25 °C the mixture is mostly N₂O₄.']},
  {id:'bigk',kind:'ap',lvl:'ap',
    q:'A reaction has K = 1 × 10⁸ at 25 °C. What does that tell you?',
    choices:['At equilibrium the mixture is almost all products','It reacts very fast','It is endothermic','Almost no products form'],correct:0,
    steps:['K compares products to reactants at equilibrium.','A K this large means products far outweigh reactants.','K says nothing about speed: a reaction with a huge K can still be slow without a catalyst.']}
  ]},
ksp:{
  apNote:'Released questions from College Board. Solubility questions compare Q with Ksp and use the common-ion effect.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'kidney',kind:'real',lvl:'bio',
    q:'Most kidney stones are calcium oxalate, a salt that is “insoluble” in water. What does “insoluble” really mean here?',
    choices:['A tiny amount dissolves, and the rest stays solid once the liquid is saturated','None of it ever dissolves','It dissolves completely but slowly','It only dissolves in acid'],correct:0,
    steps:['Every ionic solid dissolves at least a little.','Once the liquid holds as much as it can, it is saturated, and extra solid stays solid. In the body, stones form when urine holds more than that limit.','Drinking more water keeps the ions dilute, below the saturation limit. That is why doctors tell people prone to stones to drink a lot.'],
    lab:{set:{mode:'dissolve',salt:'AgCl',amt:'5'},look:'Watch ions leave the crystal until the solution is saturated. The rest stays on the bottom.'}},
  {id:'more',kind:'test',lvl:'bio',
    q:'A saturated AgCl solution sits on 5 mg of solid. You stir in 15 more mg. What happens to the amount of dissolved AgCl?',
    choices:['It stays the same','It goes up','It goes down'],correct:0,
    steps:['Saturated means the water already holds all the AgCl it can at this temperature: about 0.19 mg per 100 mL.','The extra solid just adds to the pile.','To dissolve more, you would need more water or a different temperature.'],
    lab:{set:{mode:'dissolve',salt:'AgCl',amt:'20'},look:'Read <b>Ions in solution</b>, then compare with 5 mg.'}},
  {id:'common',kind:'test',lvl:'honors',
    q:'AgCl (Ksp = 1.8 × 10⁻¹⁰) dissolves in 0.10 M NaCl. What is its molar solubility?',
    choices:['1.8 × 10⁻⁹ M','1.3 × 10⁻⁵ M','1.8 × 10⁻¹⁰ M','0.10 M'],correct:0,
    steps:['The NaCl fixes [Cl⁻] ≈ 0.10 M.','s = [Ag⁺] = Ksp ÷ [Cl⁻] = 1.8 × 10⁻¹⁰ ÷ 0.10 = 1.8 × 10⁻⁹ M.','That is about 7000 times less than in pure water (1.3 × 10⁻⁵ M): the common-ion effect.'],
    lab:{set:{mode:'dissolve',salt:'AgCl',amt:'5',common:'0.1'},look:'Read <b>Molar solubility s</b>.'}},
  {id:'mixq',kind:'test',lvl:'honors',
    q:'You mix 50 mL of 1.0 × 10⁻³ M Pb(NO₃)₂ with 50 mL of 1.0 × 10⁻³ M NaI. Ksp of PbI₂ = 9.8 × 10⁻⁹. Does PbI₂ precipitate?',
    choices:['No: Q = 1.25 × 10⁻¹⁰ is less than Ksp','Yes: Q is greater than Ksp','Yes, always, because PbI₂ is “insoluble”'],correct:0,
    steps:['Mixing doubles the volume, so [Pb²⁺] = [I⁻] = 5.0 × 10⁻⁴ M.','Q = [Pb²⁺][I⁻]² = (5.0 × 10⁻⁴)(5.0 × 10⁻⁴)² = 1.25 × 10⁻¹⁰.','Q < Ksp, so the solution stays clear. Raise both to 0.010 M and Q = 1.25 × 10⁻⁷, which is above Ksp: yellow solid forms.'],
    lab:{set:{mode:'mix',salt:'PbI2',m1:'0.001',m2:'0.001'},look:'Read <b>Ion product Q</b> and <b>Ksp</b>, then raise both solutions to 0.010 M.'}},
  {id:'caf2',kind:'test',lvl:'honors',
    q:'CaF₂ has Ksp = 3.45 × 10⁻¹¹. What is its molar solubility in pure water?',
    choices:['2.0 × 10⁻⁴ M','5.9 × 10⁻⁶ M','3.45 × 10⁻¹¹ M','8.6 × 10⁻¹² M'],correct:0,
    steps:['CaF₂ ⇌ Ca²⁺ + 2F⁻, so [Ca²⁺] = s and [F⁻] = 2s.','Ksp = s(2s)² = 4s³, so s = (3.45 × 10⁻¹¹ ÷ 4)^(1/3) = 2.0 × 10⁻⁴ M.','Fluoride toothpaste works the other way: it helps form fluorapatite, which is less soluble than tooth enamel in acid.'],
    lab:{set:{mode:'dissolve',salt:'CaF2',amt:'100'},look:'Read <b>Molar solubility s</b>.'}},
  {id:'antacid',kind:'real',lvl:'ap',
    q:'Milk of magnesia is a suspension of Mg(OH)₂. Why does it dissolve in stomach acid but not in the bottle?',
    choices:['Acid removes OH⁻, so Q drops below Ksp and more Mg(OH)₂ dissolves','Stomach acid is warmer','Ksp is larger in the stomach','It dissolves in the bottle too'],correct:0,
    steps:['Mg(OH)₂(s) ⇌ Mg²⁺ + 2OH⁻.','H₃O⁺ from stomach acid reacts with OH⁻ to make water, pulling [OH⁻] way down.','[Mg²⁺][OH⁻]² falls below Ksp, so solid keeps dissolving and neutralizing acid. Each pH unit lower raises the solubility 100 times.'],
    lab:{set:{mode:'dissolve',salt:'MgOH2',amt:'100',buf:true,pH:9},look:'Compare pH 12 with pH 9 and read the solid left in the beaker.'}},
  {id:'ag2cro4',kind:'ap',lvl:'ap',
    q:'Ag₂CrO₄ has Ksp = 1.1 × 10⁻¹². What is [Ag⁺] in a saturated solution?',
    num:{ans:1.3e-4,tol:.1e-4,unit:'M'},
    steps:['Ag₂CrO₄ ⇌ 2Ag⁺ + CrO₄²⁻, so Ksp = (2s)²(s) = 4s³.','s = (1.1 × 10⁻¹² ÷ 4)^(1/3) = 6.5 × 10⁻⁵ M.','[Ag⁺] = 2s = 1.3 × 10⁻⁴ M.']}
  ]},
ph:{
  apNote:'Released questions from College Board. pH questions test logs, strong vs weak acids and Ka.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'teeth',kind:'real',lvl:'bio',
    q:'Tooth enamel starts to dissolve below about pH 5.5. Cola has pH 2.5 and milk has pH 6.7. Which is harder on your teeth if you sip it all day?',
    choices:['Cola','Milk','They are the same'],correct:0,
    steps:['Lower pH means more acidic.','Cola at pH 2.5 is far below 5.5; milk at 6.7 is above it.','Sipping all day keeps your mouth acidic for hours. Drinking it with a meal or rinsing with water helps.'],
    lab:{set:{mode:'scale',sol:'cola'},look:'Read the pH, then try milk.'},verify:[['pH',2.5,.05]]},
  {id:'tenx',kind:'test',lvl:'bio',
    q:'Lemon juice is pH 2. Coffee is pH 5. How many times more H₃O⁺ is in the lemon juice?',
    choices:['1000 times','3 times','30 times','300 times'],correct:0,
    steps:['Each pH unit is a 10-times change in [H₃O⁺].','From pH 5 to pH 2 is 3 units.','10 × 10 × 10 = 1000 times.']},
  {id:'strongweak',kind:'test',lvl:'honors',
    q:'0.10 M HCl has pH 1.0. 0.10 M acetic acid has pH 2.9. Why are they different at the same concentration?',
    choices:['HCl ionizes completely; only about 1% of acetic acid molecules ionize','Acetic acid is more concentrated','HCl is a weak acid','Acetic acid makes OH⁻'],correct:0,
    steps:['A strong acid gives up every H⁺: [H₃O⁺] = 0.10 M, pH 1.0.','A weak acid sets up an equilibrium. For acetic acid only about 1.3% ionizes, so [H₃O⁺] ≈ 0.0013 M, pH 2.9.','Strong vs weak is about how much ionizes, not how concentrated it is.'],
    lab:{set:{mode:'compare',conc:0.1,weak:'HC2H3O2'},look:'Read both pH meters and <b>Weak acid ionized</b>.'},verify:[['pHs',1,.03],['pHw',2.88,.05]]},
  {id:'dilute',kind:'test',lvl:'honors',
    q:'You dilute 0.010 M HCl ten times with water. What is the new pH?',
    choices:['3.0','2.0','1.0','7.0'],correct:0,
    steps:['0.010 M HCl has [H₃O⁺] = 0.010 M, pH 2.0.','Diluting 10 times makes [H₃O⁺] = 0.0010 M.','pH = −log(0.0010) = 3.0.'],
    lab:{set:{mode:'compare',conc:0.001},look:'Read the pH of HCl.'},verify:[['pHs',3,.03]]},
  {id:'poh',kind:'test',lvl:'honors',
    q:'Household ammonia cleaner has pH 11.6. What is its pOH?',
    num:{ans:2.4,tol:.05},
    steps:['At 25 °C, pH + pOH = 14.00.','pOH = 14.00 − 11.6 = 2.4.','So [OH⁻] = 10^(−2.4) ≈ 4 × 10⁻³ M.'],
    lab:{set:{mode:'scale',sol:'ammonia'},look:'Read <b>pOH</b>.'},verify:[['pOH',2.4,.05]]},
  {id:'ka',kind:'ap',lvl:'ap',
    q:'0.10 M HF has pH 2.1. What is Ka for HF?',
    choices:['About 6.8 × 10⁻⁴','About 7.9 × 10⁻³','About 6.3 × 10⁻⁵','About 0.10'],correct:0,
    steps:['[H₃O⁺] = [F⁻] = 10^(−2.1) = 7.9 × 10⁻³ M.','[HF] = 0.10 − 0.0079 = 0.092 M.','Ka = (7.9 × 10⁻³)² ÷ 0.092 = 6.8 × 10⁻⁴.'],
    lab:{set:{mode:'compare',conc:0.1,weak:'HF'},look:'Read the weak acid’s pH and <b>Ka of weak acid</b>.'}},
  {id:'weakdil',kind:'ap',lvl:'ap',
    q:'You dilute 0.10 M acetic acid to 0.0010 M. What happens to the percent ionized?',
    choices:['It rises, from about 1.3% to about 12%','It stays 1.3%','It falls'],correct:0,
    steps:['For a weak acid, x ≈ √(Ka·C), so percent ionized ≈ √(Ka/C) × 100.','Cutting C by 100 raises the percent about 10 times.','More water pulls the equilibrium toward ions (Le Châtelier): more particles on the right side.'],
    lab:{set:{mode:'compare',conc:0.001,weak:'HC2H3O2'},look:'Read <b>Weak acid ionized</b> at 0.10 M and at 0.0010 M.'}}
  ]},
buffers:{
  apNote:'Released questions from College Board. Buffer questions ask what the buffer does with added acid or base, and use Henderson–Hasselbalch.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'blood',kind:'real',lvl:'bio',
    q:'During a hard workout your muscles dump acid into your blood, but your blood stays near pH 7.4. What keeps it steady?',
    choices:['A buffer: bicarbonate grabs the extra H₃O⁺','Your blood has no acid in it','Sweat removes the acid','The heart filters out H₃O⁺'],correct:0,
    steps:['Blood is buffered mainly by carbonic acid (H₂CO₃) and bicarbonate (HCO₃⁻).','Bicarbonate reacts with extra H₃O⁺, turning it into carbonic acid, which you breathe out as CO₂.','That is part of why you breathe hard during exercise.'],
    lab:{set:{dose:1},act:'acid',look:'Compare the two pH meters after adding acid.'}},
  {id:'same',kind:'test',lvl:'bio',
    q:'You add 1.0 mL of 1.0 M HCl to plain water and to a buffer at the same pH. What happens?',
    choices:['Water’s pH drops a lot; the buffer’s barely changes','Both drop the same amount','The buffer’s pH drops more','Neither changes'],correct:0,
    steps:['In water nothing takes up the H₃O⁺, so the pH drops several units.','In the buffer, the base form (like acetate) reacts with H₃O⁺ and turns it into the weak acid.','The weak acid barely ionizes, so the pH hardly moves.'],
    lab:{set:{dose:1},act:'acid',look:'Read <b>Change in water’s pH</b> and <b>Change in buffer’s pH</b>.'}},
  {id:'what',kind:'test',lvl:'honors',
    q:'Which pair makes a buffer?',
    choices:['Acetic acid and sodium acetate','HCl and NaCl','NaOH and NaCl','HCl and NaOH'],correct:0,
    steps:['A buffer needs a weak acid and its conjugate base (or a weak base and its conjugate acid).','Acetic acid is weak; acetate is its conjugate base.','HCl is strong, so Cl⁻ cannot take back H⁺; NaCl does nothing to buffer.']},
  {id:'capacity',kind:'test',lvl:'honors',
    q:'Two acetate buffers both have pH 4.74. One is 0.020 M and one is 0.50 M. How do they differ?',
    choices:['The 0.50 M buffer can absorb much more acid before its pH falls','The 0.020 M buffer is stronger','They behave the same','The 0.50 M buffer has a lower pH'],correct:0,
    steps:['pH depends on the ratio of base to acid, which is the same here.','How much acid a buffer can absorb depends on how much base form it holds.','The 0.50 M buffer holds 25 times as much, so it lasts 25 times longer.'],
    lab:{set:{sys:'acetate',conc:0.02,dose:5},act:'acid',look:'Add acid a few times, then try 0.50 M and compare.'}},
  {id:'hh',kind:'ap',lvl:'ap',
    q:'An acetate buffer (pKa 4.74) has twice as much acetate as acetic acid. What is its pH?',
    num:{ans:5.04,tol:.03},
    steps:['pH = pKa + log([A⁻]/[HA]).','= 4.74 + log 2 = 4.74 + 0.30.','= 5.04.'],
    lab:{set:{sys:'acetate',ratio:2},look:'Read <b>Henderson–Hasselbalch pH</b>.'},verify:[['hh',5.04,.02]]},
  {id:'choose',kind:'ap',lvl:'ap',
    q:'You need a buffer at pH 9.0. Which system should you use?',
    choices:['Ammonium / ammonia, pKa 9.25','Acetic acid / acetate, pKa 4.74','Phosphate, pKa 7.21','Any of them'],correct:0,
    steps:['A buffer works best within about 1 pH unit of its pKa.','9.0 is within 1 of 9.25 but far from 4.74 and 7.21.','Use a base-to-acid ratio of 10^(9.0 − 9.25) ≈ 0.56.']},
  {id:'bloodratio',kind:'ap',lvl:'ap',
    q:'Blood: pKa of H₂CO₃ is 6.1 at 37 °C and blood pH is 7.4. What is [HCO₃⁻] ÷ [H₂CO₃]?',
    num:{ans:20,tol:1},
    steps:['7.4 = 6.1 + log(ratio).','log(ratio) = 1.3.','Ratio = 10^1.3 ≈ 20. Blood holds far more base form, which suits it: the body makes much more acid than base.']}
  ]},
gibbs:{
  apNote:'Released questions from College Board. Thermodynamics questions ask for the signs of ΔH, ΔS and ΔG and when a process is favorable.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'room',kind:'real',lvl:'bio',
    q:'Someone sprays perfume in one corner of a room. Soon you can smell it everywhere. Why doesn’t it all stay in the corner?',
    choices:['There are vastly more ways for the molecules to be spread out than bunched up','Perfume molecules repel each other','Air pushes them away','It does stay in the corner'],correct:0,
    steps:['Molecules move randomly and bump into air molecules.','Spread out across the room, there are almost countless arrangements; in one corner, very few.','Random motion lands in the likely arrangements: spread out. That tendency is entropy.'],
    lab:{set:{mode:'spread',N:40,wall:false},look:'Watch the share on the left settle near half.'}},
  {id:'melt',kind:'test',lvl:'bio',
    q:'Ice melts into liquid water. What happens to entropy?',
    choices:['It increases','It decreases','It stays the same'],correct:0,
    steps:['In ice, molecules are locked in a crystal.','In liquid water they slide past each other, with many more possible arrangements.','More arrangements means higher entropy.'],
    lab:{set:{mode:'predict',proc:'melt',reveal:true},look:'Read <b>Entropy change</b>.'}},
  {id:'gasmoles',kind:'test',lvl:'honors',
    q:'For N₂(g) + 3H₂(g) → 2NH₃(g), predict the sign of ΔS°.',
    choices:['Negative: 4 moles of gas become 2','Positive: more product forms','Zero'],correct:0,
    steps:['Count moles of gas: 1 + 3 = 4 before, 2 after.','Fewer gas particles means fewer ways to arrange them.','ΔS° is negative: −198 J/K.'],
    lab:{set:{mode:'predict',proc:'haber',reveal:true},look:'Read <b>Moles of gas, before → after</b> and <b>ΔS°</b>.'}},
  {id:'lime',kind:'test',lvl:'honors',
    q:'CaCO₃ → CaO + CO₂: ΔH° = +178.3 kJ, ΔS° = +160.2 J/K. What is ΔG° at 298 K?',
    num:{ans:130.6,tol:.6,unit:'kJ'},
    steps:['ΔG = ΔH − TΔS. Change ΔS to kJ: 0.1602 kJ/K.','TΔS = 298 × 0.1602 = 47.7 kJ.','ΔG = 178.3 − 47.7 = +130.6 kJ: not spontaneous at room temperature, which is why limestone buildings last.'],
    lab:{set:{mode:'gibbs',rx:'caco3',T:298},look:'Read <b>ΔG = ΔH − TΔS</b>.'},verify:[['dG',130.6,.6]]},
  {id:'cases',kind:'test',lvl:'honors',
    q:'A reaction has ΔH < 0 and ΔS < 0. When is it spontaneous?',
    choices:['At low temperatures','At high temperatures','Always','Never'],correct:0,
    steps:['ΔG = ΔH − TΔS. With ΔS < 0, the −TΔS term is positive and grows with T.','At low T, the negative ΔH wins and ΔG < 0.','At high T, −TΔS wins and ΔG > 0. Freezing water is an example: spontaneous only below 0 °C.'],
    lab:{set:{mode:'gibbs',rx:'haber',T:298},look:'Raise the temperature and watch ΔG change sign.'}},
  {id:'freezeT',kind:'ap',lvl:'ap',
    q:'H₂O(l) → H₂O(g): ΔH° = +44.0 kJ/mol and ΔS° = +118.9 J/mol·K. Estimate the boiling point from these data.',
    num:{ans:370,tol:6,unit:'K'},
    steps:['At the boiling point, ΔG = 0, so T = ΔH ÷ ΔS.','T = 44 000 J ÷ 118.9 J/K = 370 K.','That is 97 °C, close to the real 100 °C; ΔH and ΔS change a little with temperature.'],
    lab:{set:{mode:'gibbs',rx:'boil'},act:'cross',look:'Read the <b>Crossover temperature</b>.'}},
  {id:'kfromg',kind:'ap',lvl:'ap',
    q:'A reaction has ΔG° = +10.0 kJ at 298 K. What is K?',
    choices:['About 0.018','About 56','About 1','About 10'],correct:0,
    steps:['K = e^(−ΔG°/RT).','−ΔG°/RT = −10 000 ÷ (8.314 × 298) = −4.04.','K = e^(−4.04) = 0.018. Positive ΔG° means K < 1: reactants are favored.']}
  ]},
galvanic:{
  apNote:'Released questions from College Board. Electrochemistry questions use E° tables, ΔG° = −nFE° and the direction of electron flow.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'battery',kind:'real',lvl:'bio',
    q:'A phone battery and a zinc–copper cell both make electricity from the same idea. What is it?',
    choices:['One material gives up electrons and another takes them, and the electrons travel through the wire between them','Batteries store electricity like water in a tank','Heat is turned into electricity','Electrons are created inside the battery'],correct:0,
    steps:['In the Zn–Cu cell, zinc atoms give up electrons (oxidation) and copper ions take them (reduction).','The electrons can only get from one to the other through the wire, so they power whatever is in the way.','A lithium-ion battery does the same with lithium and metal oxides, and can be pushed backward to recharge.'],
    lab:{set:{mode:'cell',left:'Zn',right:'Cu'},look:'Watch the electrons move through the wire and read the voltmeter.'}},
  {id:'zncu',kind:'test',lvl:'bio',
    q:'Zinc (E° = −0.76 V) and copper (E° = +0.34 V) half-cells are connected. What does the voltmeter read?',
    choices:['1.10 V','0.42 V','−0.42 V','0.34 V'],correct:0,
    steps:['E°cell = E°(cathode) − E°(anode).','Copper has the higher E°, so it is the cathode: 0.34 − (−0.76) = 1.10 V.','Zinc is the anode: its electrode slowly loses mass while copper builds up on the cathode.'],
    lab:{set:{mode:'cell',left:'Zn',right:'Cu',cL:1,cR:1},look:'Read the voltmeter.'},verify:[['volt',1.1,.03]]},
  {id:'bridge',kind:'test',lvl:'bio',
    q:'You pull out the salt bridge. What happens to the current?',
    choices:['It stops','It doubles','It keeps flowing the same'],correct:0,
    steps:['As the cell runs, positive charge builds up on one side and negative on the other.','The salt bridge lets ions move to balance that charge.','Without it the charge builds up immediately and electrons stop flowing.'],
    lab:{set:{mode:'cell',left:'Zn',right:'Cu',bridge:false},look:'Read <b>Current</b>.'},verify:[['mA',0,.01]]},
  {id:'mgcu',kind:'test',lvl:'honors',
    q:'Which pair makes the biggest voltage? Mg −2.37, Zn −0.76, Cu +0.34, Ag +0.80 V.',
    choices:['Mg and Ag','Zn and Cu','Cu and Ag','Mg and Zn'],correct:0,
    steps:['The voltage is the gap between the two E° values.','Mg and Ag are farthest apart: 0.80 − (−2.37) = 3.17 V.','Bigger gaps mean the metals “want” to trade electrons more.'],
    lab:{set:{mode:'cell',left:'Mg',right:'Ag'},look:'Read the voltmeter.'}},
  {id:'anode',kind:'test',lvl:'honors',
    q:'In an iron–copper cell (Fe −0.44 V, Cu +0.34 V), which electrode loses mass?',
    choices:['Iron, the anode','Copper, the cathode','Both','Neither'],correct:0,
    steps:['The lower E° metal is oxidized: Fe → Fe²⁺ + 2e⁻.','Iron atoms leave the electrode as ions, so it loses mass.','Cu²⁺ ions gain electrons and plate onto the copper, which gains mass.'],
    lab:{set:{mode:'cell',left:'Fe',right:'Cu'},look:'Read <b>Left electrode mass</b> and <b>Right electrode mass</b> as the cell runs.'}},
  {id:'dg',kind:'ap',lvl:'ap',
    q:'For Zn + Cu²⁺ → Zn²⁺ + Cu, E° = 1.10 V and n = 2. What is ΔG°? (F = 96 485 C/mol)',
    num:{ans:-212,tol:2,unit:'kJ/mol'},
    steps:['ΔG° = −nFE°.','= −2 × 96 485 × 1.10 = −212 300 J.','= −212 kJ/mol. Negative, so the cell runs on its own.'],
    lab:{set:{mode:'cell',left:'Zn',right:'Cu',cL:1,cR:1},look:'Read <b>ΔG° = −nFE°</b>.'},verify:[['dG',-212,1]]},
  {id:'nernst',kind:'ap',lvl:'ap',
    q:'In the Zn–Cu cell, you lower [Cu²⁺] to 0.001 M and keep [Zn²⁺] at 1.0 M. What happens to Ecell?',
    choices:['It drops a little, to about 1.01 V','It rises','It drops to 0','It stays 1.10 V'],correct:0,
    steps:['E = E° − (0.0592/n) log Q, with Q = [Zn²⁺]/[Cu²⁺] = 1000.','E = 1.10 − (0.0296)(3) = 1.01 V.','Less reactant on the cathode side means less push. A dead battery is a cell that has reached Q = K, where E = 0.'],
    lab:{set:{mode:'cell',left:'Zn',right:'Cu',cL:1,cR:0.001},look:'Read <b>Ecell (Nernst, now)</b>.'}}
  ]},
gaslaws:{
  apNote:'Released questions from College Board. Gas questions use PV = nRT and explain pressure as molecules hitting the walls.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'tires',kind:'real',lvl:'bio',
    q:'On the first cold morning of winter, the car’s low-tire-pressure light comes on. Nobody let air out. Why?',
    choices:['Colder air molecules move slower and hit the tire walls less often and less hard, so the pressure drops','Cold air leaks out faster','The tire gets bigger in the cold','The sensor freezes'],correct:0,
    steps:['Pressure comes from gas molecules hitting the walls.','Colder molecules move slower, so they hit less often and with less force.','A drop from 70 °F to 20 °F lowers tire pressure about 10%, enough to trip the light. Fill to the number on the door sticker when the tires are cold.'],
    lab:{set:{mode:'box',hold:'V',T:273},look:'Lower the heater and watch the pressure gauge and the wall hits.'}},
  {id:'doubleT',kind:'test',lvl:'bio',
    q:'A sealed, rigid box of gas goes from 273 K to 546 K. What happens to the pressure?',
    choices:['It doubles','It halves','It stays the same','It goes up 273 times'],correct:0,
    steps:['With volume and amount fixed, P is proportional to T in kelvins.','546 K is twice 273 K, so the pressure doubles: 1.0 atm to 2.0 atm.','Always use kelvins. In °C this would look like 0 to 273, which makes no sense as a ratio.'],
    lab:{set:{mode:'box',hold:'V',vol:22.4,T:546},look:'Read the pressure gauge.'},verify:[['P',2,.06]]},
  {id:'syringe',kind:'test',lvl:'bio',
    q:'You hold your finger over the tip of a syringe holding 10 mL of air at 1.0 atm and push the plunger to 5 mL. What is the pressure now?',
    choices:['2.0 atm','0.5 atm','1.0 atm','5.0 atm'],correct:0,
    steps:['Boyle’s law: P₁V₁ = P₂V₂ at constant temperature.','1.0 atm × 10 mL = P₂ × 5 mL, so P₂ = 2.0 atm.','Half the space means the same molecules hit the walls twice as often.'],
    lab:{set:{mode:'syringe',syr:5},look:'Read the pressure gauge.'},verify:[['P',2,.06]]},
  {id:'balloon',kind:'real',lvl:'bio',
    q:'You put a balloon in the freezer for an hour. When you take it out it looks smaller and wrinkled. Why?',
    choices:['Cold gas takes up less space at the same pressure','Air leaked out','Rubber shrinks in the cold but the air does not','The balloon froze solid'],correct:0,
    steps:['A balloon’s skin keeps the pressure inside about equal to outside.','At constant pressure, volume is proportional to kelvin temperature (Charles’s law).','Going from 295 K to 255 K shrinks it about 14%. Warm it up and it fills back out.'],
    lab:{set:{mode:'balloon',bath:'ice'},look:'Compare the balloon in ice water with the room-temperature one.'}},
  {id:'pvnrt',kind:'test',lvl:'honors',
    q:'How many moles of gas fill a 2.0 L soda bottle at 1.0 atm and 298 K? (R = 0.08206 L·atm/mol·K)',
    num:{ans:.082,tol:.002,unit:'mol'},
    steps:['n = PV ÷ RT.','= (1.0 atm × 2.0 L) ÷ (0.08206 × 298).','= 0.082 mol, which is about 2.4 g of air.']},
  {id:'combined',kind:'test',lvl:'honors',
    q:'A weather balloon holds 5.0 L at 1.0 atm and 300 K. High up, the pressure is 0.50 atm and the temperature is 240 K. What is its volume?',
    num:{ans:8,tol:.1,unit:'L'},
    steps:['Combined gas law: P₁V₁/T₁ = P₂V₂/T₂.','V₂ = V₁ × (P₁/P₂) × (T₂/T₁) = 5.0 × (1.0/0.50) × (240/300).','= 5.0 × 2 × 0.80 = 8.0 L. Lower pressure wins over the cold, so the balloon swells.']},
  {id:'realgas',kind:'ap',lvl:'ap',
    q:'At high pressure, CO₂ has a compressibility Z = PV/nRT below 1. What does that mean?',
    choices:['Attractions between CO₂ molecules pull them together, so the pressure is lower than an ideal gas would have','CO₂ molecules have no size','The gas is hotter than measured','CO₂ is an ideal gas'],correct:0,
    steps:['Ideal gases have Z = 1 exactly.','Z < 1 means less pressure than ideal: molecules pull on each other and hit the walls less hard.','CO₂ is large and polarizable, so its attractions are strong. Helium stays much closer to ideal.'],
    lab:{set:{mode:'box',gas:'CO2',vol:2,T:300,mol:1.5},look:'Read <b>Compressibility Z</b>, then switch the gas to helium.'}}
  ]},
kmt:{
  apNote:'Released questions from College Board. Kinetic molecular theory questions link temperature to average kinetic energy and mass to speed.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'pizza',kind:'real',lvl:'bio',
    q:'Someone opens a pizza box across the cafeteria. A few seconds later you smell it. What carried the smell?',
    choices:['Fast-moving odor molecules bumping their way through the air','Sound waves','Light','The smell only travels if there is a fan'],correct:0,
    steps:['At room temperature, air and odor molecules move hundreds of meters per second.','They collide billions of times a second, so they wander instead of flying straight.','That random wandering, called diffusion, still brings them across the room in seconds.'],
    lab:{set:{mode:'race',pair:'hcl'},look:'Watch the two gases spread toward each other down the tube.'}},
  {id:'heat',kind:'test',lvl:'bio',
    q:'You heat a gas from 300 K to 600 K. What happens to the average kinetic energy of its molecules?',
    choices:['It doubles','It quadruples','It stays the same','It halves'],correct:0,
    steps:['Average kinetic energy is proportional to kelvin temperature.','Twice the kelvin temperature means twice the average kinetic energy.','The speed rises less, by √2 ≈ 1.41, because KE = ½mv².'],
    lab:{set:{mode:'dist',gasA:'N2',T:600},look:'Read <b>Average kinetic energy</b> at 300 K and 600 K.'}},
  {id:'same',kind:'test',lvl:'bio',
    q:'Helium and xenon are in the same room at the same temperature. Which statement is true?',
    choices:['They have the same average kinetic energy, but helium moves much faster','Xenon moves faster because it is heavier','They move at the same speed','Helium has more kinetic energy'],correct:0,
    steps:['Same temperature means same average kinetic energy.','KE = ½mv², so the lighter gas must move faster.','Helium (4 g/mol) moves about √(131/4) ≈ 5.7 times faster than xenon (131 g/mol).'],
    lab:{set:{mode:'dist',gasA:'He',gasB:'Xe',T:300},look:'Compare the two average speeds and the two average kinetic energies.'}},
  {id:'urms',kind:'test',lvl:'honors',
    q:'What is the rms speed of N₂ (0.0280 kg/mol) at 300 K? (R = 8.314 J/mol·K)',
    num:{ans:517,tol:5,unit:'m/s'},
    steps:['u_rms = √(3RT/M).','= √(3 × 8.314 × 300 ÷ 0.0280).','= √267 000 ≈ 517 m/s, faster than a passenger jet.'],
    lab:{set:{mode:'dist',gasA:'N2',T:300},look:'Read <b>u_rms = √(3RT/M)</b>.'},verify:[['rmsT',517,3]]},
  {id:'ring',kind:'test',lvl:'honors',
    q:'NH₃ (17.0 g/mol) and HCl (36.5 g/mol) enter opposite ends of a glass tube. A white ring of NH₄Cl forms where they meet. Where?',
    choices:['Closer to the HCl end, because NH₃ moves faster','Closer to the NH₃ end','Exactly in the middle'],correct:0,
    steps:['Lighter molecules move faster at the same temperature.','Graham’s law: rate(NH₃)/rate(HCl) = √(36.5/17.0) = 1.46.','NH₃ travels about 1.46 times as far, so the ring forms about 59% of the way to the HCl end.'],
    lab:{set:{mode:'race',pair:'hcl'},look:'Read <b>Distance ratio (base ÷ acid)</b> when the ring forms.'}},
  {id:'balloonhe',kind:'real',lvl:'honors',
    q:'A helium party balloon is flat by the next morning, but an air-filled one lasts days. Why?',
    choices:['Light helium atoms move fast and escape through tiny gaps in the rubber far more often','Helium reacts with rubber','Air is lighter than helium','Helium gets colder overnight'],correct:0,
    steps:['Effusion rate is proportional to 1/√M.','Air averages about 29 g/mol, helium 4.0 g/mol: helium escapes √(29/4) ≈ 2.7 times faster.','Foil balloons last longer because metal-coated film has far smaller gaps.'],
    lab:{set:{mode:'effuse',gasA:'He',gasB:'N2',T:300},look:'Compare the two escape rates.'}},
  {id:'graham',kind:'ap',lvl:'ap',
    q:'An unknown gas effuses 0.50 times as fast as helium (4.00 g/mol). What is its molar mass?',
    num:{ans:16,tol:.2,unit:'g/mol'},
    steps:['rate(unknown)/rate(He) = √(M_He/M_unknown).','0.50 = √(4.00/M), so 0.25 = 4.00/M.','M = 16.0 g/mol: methane.']}
  ]},
states:{
  apNote:'Released questions from College Board. Phase-change questions ask why the temperature stays flat and how much heat each step takes.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'pasta',kind:'real',lvl:'bio',
    q:'Your pasta water is at a full boil. You turn the burner up to high. What happens to the water’s temperature?',
    choices:['It stays at the boiling point; the water just boils away faster','It rises above 100 °C','It drops','It doubles'],correct:0,
    steps:['While water boils, the added heat goes into pulling molecules apart into gas, not into speeding them up.','So the temperature stays flat at the boiling point (about 95 °C in Aurora or Denver).','Turning it up only boils it off faster. A gentle boil cooks pasta just as fast and saves energy.'],
    lab:{set:{sub:'water',start:'liquid',power:100},look:'Watch the heating curve go flat while the water boils.'}},
  {id:'flat',kind:'test',lvl:'bio',
    q:'On a heating curve for ice, the line goes flat at 0 °C for a while. What is the heat doing then?',
    choices:['Breaking the attractions that hold the ice crystal together','Speeding up the molecules','Nothing; the heater is off','Making the water colder'],correct:0,
    steps:['Temperature measures how fast particles move on average.','During melting, the energy goes into breaking the crystal apart, so the speed (and temperature) stays the same.','Once all the ice has melted, the temperature starts rising again.'],
    lab:{set:{sub:'water',start:'solid',power:50},look:'Read <b>State</b> and the temperature during the flat part.'}},
  {id:'cool',kind:'test',lvl:'bio',
    q:'Steam is cooled until it turns back into liquid. Is heat released or absorbed during condensing?',
    choices:['Released','Absorbed','Neither'],correct:0,
    steps:['Boiling takes energy to pull molecules apart.','Condensing is the reverse, so the same energy comes back out.','That is why a steam burn is worse than a hot-water burn: the steam releases 2260 J per gram as it condenses on your skin.'],
    lab:{set:{sub:'water',start:'gas',power:-50},look:'Read <b>Heat flow</b> while the steam condenses.'}},
  {id:'meltq',kind:'test',lvl:'honors',
    q:'How much heat melts 50 g of ice at 0 °C? (ΔH_fus = 334 J/g)',
    num:{ans:16.7,tol:.2,unit:'kJ'},
    steps:['q = m × ΔH_fus.','= 50 g × 334 J/g = 16 700 J.','= 16.7 kJ, with no temperature change at all.'],
    lab:{set:{sub:'water',start:'solid',mass:50,power:50},look:'Read <b>Heat added since start</b> when the ice has just finished melting.'}},
  {id:'boilq',kind:'test',lvl:'honors',
    q:'Which takes more heat for 50 g of water: melting it at 0 °C, or boiling it away at 100 °C? (ΔH_fus = 334 J/g, ΔH_vap = 2260 J/g)',
    choices:['Boiling, about 6.8 times as much','Melting','They are the same'],correct:0,
    steps:['Melting: 50 × 334 = 16.7 kJ.','Boiling: 50 × 2260 = 113 kJ.','Boiling must pull molecules completely apart, while melting only loosens the crystal.'],
    lab:{set:{sub:'water',start:'solid',mass:50,power:100},look:'Compare how long the two flat parts of the curve last.'}},
  {id:'argon',kind:'test',lvl:'honors',
    q:'Argon boils at −186 °C and water at 100 °C. What does that say about the attractions between particles?',
    choices:['Argon atoms attract each other much more weakly than water molecules do','Argon atoms attract each other more strongly','Argon is heavier, so it boils lower','Boiling point has nothing to do with attractions'],correct:0,
    steps:['To boil, particles need enough energy to escape their neighbors.','Argon atoms have only weak London dispersion attractions.','Water molecules hydrogen-bond to each other, which takes much more energy to overcome.'],
    lab:{set:{sub:'ar',start:'solid'},look:'Heat argon and compare its curve with water’s.'}},
  {id:'press',kind:'ap',lvl:'ap',
    q:'You raise the pressure on boiling water from 1.0 atm to 2.0 atm. What happens to its boiling point?',
    choices:['It rises to about 120 °C','It falls to about 80 °C','It stays 100 °C'],correct:0,
    steps:['Water boils when its vapor pressure equals the pressure on it.','At 2 atm the molecules need more energy to push back, so the boiling point rises to about 120 °C.','That is how a pressure cooker cooks beans in a third of the time.'],
    lab:{set:{sub:'water',P:2},look:'Read <b>Boiling point at this pressure</b>.'}}
  ]},
phasediagram:{
  apNote:'Released questions from College Board. Phase diagrams appear with vapor pressure and intermolecular forces.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'denver',kind:'real',lvl:'bio',
    q:'Box instructions say to boil pasta longer at high altitude. In Aurora (about 0.83 atm), water boils at about 95 °C. Why does lower air pressure lower the boiling point?',
    choices:['Water molecules need less energy to escape when less air is pushing down on the surface','The air is colder up high','Water is thinner at altitude','Altitude has no effect'],correct:0,
    steps:['Water boils when its vapor pressure matches the pressure above it.','Less pressure above means it reaches that point at a lower temperature.','Cooler boiling water cooks food more slowly, so you cook longer.'],
    lab:{set:{scene:'denver'},act:'go',look:'Read <b>Boiling point at this pressure</b>.'}},
  {id:'dryice',kind:'test',lvl:'bio',
    q:'Dry ice (solid CO₂) sits on the counter at 1 atm. What does it turn into?',
    choices:['A gas, directly: it sublimes','A liquid, then a gas','A liquid only','It stays solid'],correct:0,
    steps:['Find 1 atm on CO₂’s phase diagram.','At 1 atm there is no liquid region: the triple point is at 5.1 atm.','So warming solid CO₂ at 1 atm turns it straight into gas at −78.5 °C.'],
    lab:{set:{sub:'co2',scene:'dryice'},act:'go',look:'Watch the point move across the diagram from solid to gas.'}},
  {id:'triple',kind:'test',lvl:'honors',
    q:'What is special about the triple point?',
    choices:['Solid, liquid and gas can all exist together there','It is the highest temperature a liquid can reach','It is where a substance freezes','Only gas exists there'],correct:0,
    steps:['The three phase lines meet at one point.','At exactly that temperature and pressure all three phases are stable together.','For water it is 0.01 °C and 0.006 atm.'],
    lab:{set:{sub:'water'},look:'Read <b>Triple and critical points</b>.'}},
  {id:'cooker',kind:'real',lvl:'honors',
    q:'A pressure cooker holds steam at about 2.0 atm. About what temperature is the boiling water inside?',
    choices:['About 120 °C','About 100 °C','About 80 °C','About 200 °C'],correct:0,
    steps:['On water’s diagram, follow the liquid–gas line up to 2 atm.','That line crosses 2 atm near 120 °C.','Hotter water cooks faster, which is why a pressure cooker makes tough meat tender in under an hour.'],
    lab:{set:{scene:'cooker'},act:'go',look:'Read <b>Boiling point at this pressure</b>.'}},
  {id:'skate',kind:'test',lvl:'honors',
    q:'Water’s solid–liquid line tilts slightly left. What does that mean?',
    choices:['Squeezing ice can melt it, because liquid water is denser than ice','Squeezing ice makes it colder','Ice is denser than water','Water cannot freeze under pressure'],correct:0,
    steps:['A line tilting left means the melting point drops as pressure rises.','That happens because liquid water takes up less space than ice: pressure favors the denser phase.','The effect is small (about 0.0075 °C per atm), so skating works mostly because of friction heating and a thin liquid-like layer on the ice.'],
    lab:{set:{scene:'skate'},act:'go',look:'Read <b>Melting point at this pressure</b>.'}},
  {id:'scf',kind:'ap',lvl:'ap',
    q:'Above 31 °C and 73 atm, CO₂ is a supercritical fluid. Coffee companies use it to remove caffeine. What is a supercritical fluid?',
    choices:['A state past the critical point where liquid and gas are no longer different','A very cold solid','A liquid that boils at any pressure','A mixture of solid and gas'],correct:0,
    steps:['The liquid–gas line on a phase diagram ends at the critical point.','Past it, there is no boiling: the substance flows like a gas but dissolves things like a liquid.','Supercritical CO₂ dissolves caffeine, then turns to gas when the pressure drops, leaving no solvent in the beans.'],
    lab:{set:{sub:'co2',scene:'scf'},act:'go',look:'Read <b>Phase</b> and find the critical point.'}}
  ]},
airbag:{
  apNote:'Released questions from College Board. Gas stoichiometry links moles from a balanced equation to volume with PV = nRT.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'volcano',kind:'real',lvl:'bio',
    q:'For a science fair volcano you add more and more baking soda to the same cup of vinegar. After a point, the fizzing stops getting bigger. Why?',
    choices:['The vinegar ran out: it is the limiting reactant','Baking soda stops working in large amounts','The cup is too small','Extra baking soda absorbs the gas'],correct:0,
    steps:['NaHCO₃ + HC₂H₃O₂ → NaC₂H₃O₂ + H₂O + CO₂. Each reaction uses one of each.','Once the acetic acid is used up, extra baking soda has nothing to react with.','The extra just sits in the cup as white powder.'],
    lab:{set:{soda:5.2,vin:37},act:'mix',look:'Read <b>How full the bag is</b> and whether baking soda is left over.'}},
  {id:'mass',kind:'test',lvl:'bio',
    q:'A sealed bag of baking soda and vinegar weighs 50.00 g. You mix them and the bag puffs up with CO₂. What does it weigh now?',
    choices:['50.00 g','Less, because gas is weightless','More, because something new formed'],correct:0,
    steps:['Atoms are rearranged, not created or destroyed.','The CO₂ is still inside the sealed bag, so all the mass is still there.','Open the bag and the CO₂ escapes: then the mass drops.']},
  {id:'molco2',kind:'test',lvl:'honors',
    q:'2.60 g of NaHCO₃ (84.01 g/mol) reacts completely with vinegar. How many moles of CO₂ form?',
    num:{ans:.0309,tol:.0005,unit:'mol'},
    steps:['n(NaHCO₃) = 2.60 ÷ 84.01 = 0.0309 mol.','NaHCO₃ and CO₂ are 1 to 1 in the equation.','So 0.0309 mol of CO₂ forms, if there is enough vinegar.'],
    lab:{set:{soda:2.6,vin:60},act:'mix',look:'Read <b>Moles of CO₂ made</b>.'},verify:[['nco2',.0309,.0005]]},
  {id:'volume',kind:'test',lvl:'honors',
    q:'0.0309 mol of CO₂ forms in a classroom at 0.83 atm and 22 °C (295 K). What volume does it fill? (R = 0.08206)',
    num:{ans:.902,tol:.01,unit:'L'},
    steps:['V = nRT ÷ P.','= 0.0309 × 0.08206 × 295 ÷ 0.83.','= 0.90 L, about a quart bag. At sea level the same gas would fill only 0.75 L.'],
    lab:{set:{soda:2.6,vin:60,place:'rj',temp:22},act:'mix',look:'Read <b>CO₂ in the bag</b>.'},verify:[['vgas',.902,.01]]},
  {id:'gallon',kind:'real',lvl:'honors',
    q:'A gallon bag (3.785 L) at RJ needs about 4 times the CO₂ of a quart bag. What else changes?',
    choices:['You need about 4 times the baking soda and 4 times the vinegar','Only more baking soda','Only more vinegar','Nothing; more pressure fills it'],correct:0,
    steps:['Volume is proportional to moles of gas at the same T and P.','Every mole of CO₂ uses a mole of NaHCO₃ and a mole of acetic acid.','So both reactants scale by 4: about 10.4 g of baking soda and about 150 mL of vinegar.'],
    lab:{set:{bag:'gallon',soda:10.4,vin:150},act:'mix',look:'Read <b>How full the bag is</b>.'}},
  {id:'azide',kind:'ap',lvl:'ap',
    q:'A car air bag needs 3.0 mol of N₂ (2NaN₃ → 2Na + 3N₂). How many moles of NaN₃ must react?',
    num:{ans:2,tol:.01,unit:'mol'},
    steps:['The ratio is 2 NaN₃ : 3 N₂.','n(NaN₃) = 3.0 × (2/3) = 2.0 mol.','That is 2.0 × 65.01 = 130 g of sodium azide.']}
  ]},
gasstoich:{
  apNote:'Released questions from College Board. Gas-over-water labs test Dalton’s law and PV = nRT.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'dalton',kind:'test',lvl:'bio',
    q:'You collect hydrogen gas in a tube over water. Why is the gas in the tube not pure hydrogen?',
    choices:['Water evaporates into the tube, so it also holds water vapor','Air always leaks in','Hydrogen turns into water','The tube is full of oxygen'],correct:0,
    steps:['Water molecules escape from the surface into any gas space above it.','At 22 °C water vapor adds about 20 mmHg of pressure.','So the dry H₂ pressure is the room pressure minus the water vapor pressure.'],
    lab:{set:{mode:'mg'},look:'Read <b>Water vapor pressure (table)</b> and <b>Pressure of the dry gas you used</b>.'}},
  {id:'mgmol',kind:'test',lvl:'bio',
    q:'Mg + 2HCl → MgCl₂ + H₂. You react 0.0300 g of Mg (24.31 g/mol). How many moles of H₂ should form?',
    num:{ans:.00123,tol:.00003,unit:'mol'},
    steps:['n(Mg) = 0.0300 ÷ 24.31 = 0.00123 mol.','Mg and H₂ are 1 to 1.','So 0.00123 mol of H₂.'],
    lab:{set:{mode:'mg',mgMass:.03},look:'Read <b>Moles of Mg = moles of H₂ expected</b>.'}},
  {id:'pdry',kind:'test',lvl:'honors',
    q:'Room pressure is 630 mmHg and the water is at 22 °C (vapor pressure 19.8 mmHg). What is the pressure of the dry hydrogen?',
    num:{ans:610.2,tol:.5,unit:'mmHg'},
    steps:['Dalton’s law: P_total = P_H₂ + P_water.','P_H₂ = 630 − 19.8 = 610.2 mmHg.','Forgetting this step makes your moles of H₂ about 3% too high.'],
    lab:{set:{mode:'mg',Pbar:630,Tw:22},look:'Read <b>Pressure of the dry gas you used</b>.'},verify:[['Pdry',610.2,.6]]},
  {id:'butane',kind:'real',lvl:'honors',
    q:'You bubble butane from a lighter into an upside-down cylinder of water. The lighter loses 0.120 g, and the dry gas is 0.00206 mol. What is butane’s molar mass?',
    num:{ans:58.3,tol:.5,unit:'g/mol'},
    steps:['Molar mass = mass ÷ moles.','= 0.120 g ÷ 0.00206 mol = 58.3 g/mol.','Butane, C₄H₁₀, is 58.12 g/mol. Drying the lighter before reweighing matters: water on it makes the mass loss look smaller.']},
  {id:'mistake',kind:'test',lvl:'honors',
    q:'Your Mg ribbon had a dull oxide coating (8% MgO). How does that change your measured H₂?',
    choices:['Less H₂ than expected, because MgO makes no hydrogen','More H₂','No change'],correct:0,
    steps:['MgO + 2HCl → MgCl₂ + H₂O: no hydrogen.','So 8% of the ribbon’s mass makes no gas.','Your percent yield comes out about 92%. Sanding the ribbon first fixes it.'],
    lab:{set:{mode:'mg',errM:'oxide'},look:'Read <b>Percent yield of H₂</b>.'}},
  {id:'rval',kind:'ap',lvl:'ap',
    q:'You collect 32.6 mL of dry H₂ at 0.803 atm and 295 K from 0.00108 mol of Mg. What value of R do your data give?',
    num:{ans:.0822,tol:.001,unit:'L·atm/(mol·K)'},
    steps:['R = PV ÷ nT.','= 0.803 × 0.0326 ÷ (0.00108 × 295).','= 0.0822, within 0.2% of 0.08206.']}
  ]},
dissolve:{
  apNote:'Released questions from College Board. Dissolving questions connect particle-level pictures to electrolytes and solubility.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'tea',kind:'real',lvl:'bio',
    q:'Sugar dissolves faster in hot tea than in iced tea. Why?',
    choices:['Hot water molecules move faster and pull sugar molecules away from the crystal more often','Hot water is wetter','Sugar melts in hot tea','Cold water cannot dissolve sugar'],correct:0,
    steps:['Dissolving happens where water molecules hit the sugar’s surface.','Faster-moving molecules hit more often and harder.','Hot water also holds more sugar in the end, which is why sweet tea is sweetened while hot.'],
    lab:{set:{solute:'sugar',mass:20,T:80},look:'Compare <b>Time to dissolve</b> at 80 °C and 20 °C.'}},
  {id:'saltions',kind:'test',lvl:'bio',
    q:'When table salt dissolves, what does it break into?',
    choices:['Na⁺ and Cl⁻ ions, each surrounded by water molecules','Whole NaCl molecules','Sodium metal and chlorine gas','Nothing; it just becomes invisible'],correct:0,
    steps:['NaCl is ionic: a crystal of Na⁺ and Cl⁻.','Water’s slightly negative O end pulls on Na⁺; its slightly positive H ends pull on Cl⁻.','The ions drift off surrounded by water, which is why salt water conducts electricity.'],
    lab:{set:{solute:'NaCl',mass:20,stir:true},look:'Zoom in on the particles and watch the conductivity bulb.'}},
  {id:'oil',kind:'test',lvl:'bio',
    q:'Why does oil not dissolve in water, no matter how long you stir?',
    choices:['Water molecules attract each other far more than they attract nonpolar oil','Oil is heavier than water','Oil molecules are charged','You need hotter water'],correct:0,
    steps:['Water molecules are polar and stick to each other through hydrogen bonds.','Oil is nonpolar, so water gains nothing by surrounding it.','“Like dissolves like.” Soap works because one end of each soap molecule likes water and the other likes oil.'],
    lab:{set:{solute:'oil',mass:10,stir:true},look:'Watch the oil break into droplets, then separate.'}},
  {id:'saturated',kind:'test',lvl:'honors',
    q:'About 36 g of NaCl dissolves in 100 g of water at 25 °C. You add 50 g. What do you have?',
    choices:['A saturated solution with about 14 g of solid left','An unsaturated solution','A supersaturated solution','All 50 g dissolves with stirring'],correct:0,
    steps:['36 g is the most that dissolves at 25 °C.','Once 36 g has dissolved the solution is saturated.','The other 14 g stays on the bottom however long you stir.'],
    lab:{set:{solute:'NaCl',mass:50,stir:true},act:'ff',look:'Read <b>Dissolved</b> and <b>Still undissolved</b>.'}},
  {id:'electro',kind:'test',lvl:'honors',
    q:'Which is a strong electrolyte?',
    choices:['Hydrogen chloride, HCl','Sugar','Ethanol','Acetic acid'],correct:0,
    steps:['A strong electrolyte breaks into ions completely in water.','HCl ionizes almost 100%: H₃O⁺ and Cl⁻.','Acetic acid is weak (under 1% ionized at 1 M); sugar and ethanol make no ions.'],
    lab:{set:{solute:'HCl',mass:3.6,stir:true},look:'Read <b>Electrolyte type</b> and watch the bulb.'}},
  {id:'molar',kind:'ap',lvl:'ap',
    q:'20.0 g of NaCl (58.44 g/mol) dissolves in water to make 0.250 L of solution. What is the molarity?',
    num:{ans:1.37,tol:.01,unit:'M'},
    steps:['n = 20.0 ÷ 58.44 = 0.342 mol.','M = n ÷ V = 0.342 ÷ 0.250.','= 1.37 M. In that solution [Na⁺] = [Cl⁻] = 1.37 M.']}
  ]},
molarity:{
  apNote:'Released questions from College Board. Solution questions use M = n/V and M₁V₁ = M₂V₂.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'koolaid',kind:'real',lvl:'bio',
    q:'One packet of drink mix makes 2 quarts. You use one packet in 4 quarts of water. How does it taste?',
    choices:['Half as strong: the same mix spread through twice the water','Twice as strong','The same'],correct:0,
    steps:['Concentration = amount of solute ÷ volume.','Same amount, twice the volume, half the concentration.','Molarity works the same way: moles of solute ÷ liters of solution.'],
    lab:{set:{mode:'beaker',solute:'CuSO4',n:0.5,V:1},look:'Compare the color at 0.50 L and 1.00 L.'},verify:[['M',.5,.005]]},
  {id:'mcalc',kind:'test',lvl:'bio',
    q:'0.30 mol of solute is dissolved to make 0.60 L of solution. What is the molarity?',
    num:{ans:.5,tol:.005,unit:'M'},
    steps:['M = moles ÷ liters.','= 0.30 ÷ 0.60.','= 0.50 M.'],
    lab:{set:{mode:'beaker',solute:'CuSO4',n:0.3,V:0.6},look:'Read the concentration.'},verify:[['M',.5,.005]]},
  {id:'weigh',kind:'test',lvl:'honors',
    q:'You need 250.00 mL of 0.100 M CuSO₄ from CuSO₄·5H₂O crystals (249.69 g/mol). What mass do you weigh out?',
    num:{ans:6.24,tol:.02,unit:'g'},
    steps:['n = M × V = 0.100 × 0.25000 = 0.0250 mol.','Use the molar mass of the hydrate, water included: 249.69 g/mol.','m = 0.0250 × 249.69 = 6.24 g.'],
    lab:{set:{mode:'flask',solute:'CuSO4',fl:'250',mg:6.24},act:'skip',look:'Read the final concentration.'},verify:[['M',.1,.002]]},
  {id:'dilute',kind:'test',lvl:'honors',
    q:'How do you make 100.00 mL of 0.050 M CuSO₄ from 1.00 M stock?',
    choices:['Pipet 5.00 mL of stock into a 100.00 mL flask and fill to the mark with water','Add 5.00 mL of stock to 100.00 mL of water','Pipet 50.00 mL of stock into the flask','Add 95 mL of stock to 5 mL of water'],correct:0,
    steps:['M₁V₁ = M₂V₂: V₁ = 0.050 × 100.00 ÷ 1.00 = 5.00 mL.','Filling to the mark makes the total volume exactly 100.00 mL.','Adding stock to 100 mL of water gives 105 mL and the wrong concentration.'],
    lab:{set:{mode:'dilute',solute:'CuSO4',M1:1,V1:'5',V2:'100'},act:'skip',look:'Read <b>Diluted concentration M₂</b>.'},verify:[['M2',.05,.001]]},
  {id:'factor',kind:'test',lvl:'honors',
    q:'You pipet 10.00 mL of 0.80 M stock into a 250.00 mL flask and fill to the mark. What is M₂?',
    num:{ans:.032,tol:.0005,unit:'M'},
    steps:['Dilution factor = 250.00 ÷ 10.00 = 25.','M₂ = 0.80 ÷ 25.','= 0.032 M.'],
    lab:{set:{mode:'dilute',solute:'CuSO4',M1:.8,V1:'10',V2:'250'},act:'skip',look:'Read <b>Diluted concentration M₂</b>.'},verify:[['M2',.032,.0005]]},
  {id:'ppm',kind:'ap',lvl:'ap',
    q:'Drinking water may contain up to 1.3 ppm copper. How many milligrams of copper is that per liter? (1 L of water ≈ 1000 g)',
    num:{ans:1.3,tol:.01,unit:'mg/L'},
    steps:['1 ppm = 1 g of solute per 1 000 000 g of solution.','1 L ≈ 1000 g, so 1 ppm ≈ 1 mg per liter.','1.3 ppm ≈ 1.3 mg/L, the EPA action level for copper.']}
  ]},
solcurve:{
  apNote:'Released questions from College Board. Solubility curves show up in data-analysis questions and with recrystallization.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'rockcandy',kind:'real',lvl:'bio',
    q:'To grow rock candy, you dissolve lots of sugar in boiling water and let it cool on a string. Why do crystals grow?',
    choices:['Cool water holds less sugar, so the extra comes back out as crystals','The string makes sugar','Air adds sugar','The water freezes'],correct:0,
    steps:['Sugar is much more soluble in hot water.','As it cools, the water holds more sugar than it can at that temperature.','The extra sugar comes out onto the string, molecule by molecule.'],
    lab:{set:{view:'solid',solute:'KNO3',mass:80,T:30},look:'Cool the solution and watch crystals form.'}},
  {id:'kno3',kind:'test',lvl:'bio',
    q:'80 g of KNO₃ is dissolved in 100 g of water at 70 °C. You cool it to 30 °C, where only about 46 g dissolves. How much comes out as crystals?',
    choices:['About 34 g','About 46 g','About 80 g','None'],correct:0,
    steps:['At 30 °C the water holds about 46 g.','80 − 46 = 34 g has nowhere to go.','It crystallizes out. This is how chemists purify solids.'],
    lab:{set:{view:'solid',solute:'KNO3',mass:80,T:30},look:'Read <b>Undissolved</b>.'}},
  {id:'fish',kind:'real',lvl:'bio',
    q:'Why do fish kills happen more often in hot summers?',
    choices:['Warm water holds less dissolved oxygen','Fish get sunburned','Warm water holds more oxygen','Oxygen dissolves only in cold water'],correct:0,
    steps:['Gases are less soluble in warmer water: the opposite of most solids.','A pond at 30 °C holds about a third less O₂ than at 10 °C.','Add algae dying and using up oxygen, and fish can suffocate.'],
    lab:{set:{view:'gas',T:30},look:'Read <b>Dissolved O₂</b> and <b>For fish this water is</b>, then try 10 °C.'}},
  {id:'unsat',kind:'test',lvl:'honors',
    q:'KCl dissolves about 40 g per 100 g of water at 40 °C. You have 25 g in 100 g of water at 40 °C. How much more can dissolve?',
    num:{ans:15,tol:1.5,unit:'g'},
    steps:['Read the curve: about 40 g at 40 °C.','40 − 25 = 15 g more.','The solution is unsaturated.'],
    lab:{set:{view:'solid',solute:'KCl',mass:25,T:40},look:'Read <b>Can still dissolve</b>.'}},
  {id:'seed',kind:'test',lvl:'honors',
    q:'A supersaturated sodium acetate solution sits quietly. You drop in one tiny crystal. What happens?',
    choices:['Crystals spread through it quickly as the extra solute comes out','The crystal dissolves','Nothing changes'],correct:0,
    steps:['A supersaturated solution holds more than it should at that temperature.','A seed crystal gives the extra solute a place to start building.','Reusable hand warmers work this way: clicking the metal disk starts crystals, which release heat.'],
    lab:{set:{view:'solid',solute:'KNO3',mass:60,T:30,undist:true},act:'seed',look:'Watch the crystals form after the seed goes in.'}},
  {id:'pct',kind:'ap',lvl:'ap',
    q:'A saturated solution has 46 g of KNO₃ in 100 g of water. What is its mass percent?',
    num:{ans:31.5,tol:.3,unit:'%'},
    steps:['Mass percent = solute ÷ (solute + solvent) × 100.','= 46 ÷ 146 × 100.','= 31.5%.']}
  ]},
colligative:{
  apNote:'Released questions from College Board. Colligative properties depend on the number of dissolved particles, not their identity.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'roads',kind:'real',lvl:'bio',
    q:'Before a snowstorm, CDOT trucks spread salt and magnesium chloride brine on I-225. How does that help?',
    choices:['Dissolved ions lower the freezing point, so water stays liquid below 0 °C','Salt heats the road','Salt makes ice slippery','Salt absorbs snow'],correct:0,
    steps:['Particles dissolved in water get in the way of ice forming.','So the solution must be colder than 0 °C before it freezes.','Each NaCl unit makes 2 particles; each MgCl₂ makes 3, so MgCl₂ works at lower temperatures.'],
    lab:{set:{view:'freeze',solute:'nacl',m:1},look:'Read <b>Freezing point of the solution</b>.'}},
  {id:'particles',kind:'test',lvl:'bio',
    q:'At the same molality, which lowers the freezing point of water most?',
    choices:['CaCl₂','NaCl','Sugar','Ethylene glycol'],correct:0,
    steps:['Freezing-point lowering depends on the number of dissolved particles.','CaCl₂ → Ca²⁺ + 2Cl⁻: 3 particles. NaCl: 2. Sugar and ethylene glycol: 1.','So CaCl₂ wins, which is why it is sold as “ice melt.”'],
    lab:{set:{view:'freeze',solute:'cacl2',m:1},look:'Compare the freezing point with sugar at the same molality.'}},
  {id:'dtf',kind:'test',lvl:'honors',
    q:'What is the freezing point of 1.0 m NaCl in water? (Kf = 1.86 °C/m, i = 2)',
    num:{ans:-3.72,tol:.05,unit:'°C'},
    steps:['ΔTf = i·Kf·m = 2 × 1.86 × 1.0 = 3.72 °C.','The freezing point drops by that much.','Tf = 0 − 3.72 = −3.72 °C.'],
    lab:{set:{view:'freeze',solute:'nacl',m:1,realI:false},look:'Read <b>ΔTf = i·Kf·m</b>.'},verify:[['dTf',3.72,.03]]},
  {id:'antifreeze',kind:'real',lvl:'honors',
    q:'Ethylene glycol antifreeze also raises the boiling point of the radiator coolant. What is the boiling point of 3.0 m ethylene glycol? (Kb = 0.512 °C/m, i = 1)',
    num:{ans:101.54,tol:.05,unit:'°C'},
    steps:['ΔTb = i·Kb·m = 1 × 0.512 × 3.0 = 1.54 °C.','Tb = 100 + 1.54 = 101.54 °C.','Real coolant is about 50% glycol (far more than 3 m), and the radiator is pressurized, so it boils above 120 °C.'],
    lab:{set:{view:'boil',solute:'eg',m:3},look:'Read <b>ΔTb = i·Kb·m</b>.'},verify:[['dTb',1.54,.02]]},
  {id:'vp',kind:'test',lvl:'honors',
    q:'Why does a solute lower water’s vapor pressure?',
    choices:['Solute particles take up some of the surface, so fewer water molecules can escape each second','The solute holds the water down chemically','The solution is colder','It raises the vapor pressure'],correct:0,
    steps:['Only molecules at the surface can evaporate.','Dissolved particles take up some of those surface spots.','Fewer escapes means lower vapor pressure, which is also why the boiling point rises.'],
    lab:{set:{view:'vapor',solute:'sugar',m:2},look:'Read <b>Vapor pressure at 25 °C</b> and compare with pure water.'}},
  {id:'molarmass',kind:'ap',lvl:'ap',
    q:'1.00 g of an unknown molecular compound in 25.0 g of water lowers the freezing point by 0.620 °C. What is its molar mass? (Kf = 1.86)',
    num:{ans:120,tol:2,unit:'g/mol'},
    steps:['m = ΔTf ÷ Kf = 0.620 ÷ 1.86 = 0.333 mol/kg.','Moles = 0.333 × 0.0250 kg = 0.00833 mol.','M = 1.00 g ÷ 0.00833 mol = 120 g/mol.']},
  {id:'vanthoff',kind:'ap',lvl:'ap',
    q:'NaCl should have i = 2, but measured values at 1 m are closer to 1.8. Why?',
    choices:['Some Na⁺ and Cl⁻ pair up in solution, so there are fewer free particles','NaCl does not dissolve fully','The thermometer is wrong','Water forms extra ions'],correct:0,
    steps:['At higher concentrations, oppositely charged ions sometimes stick together as ion pairs.','An ion pair counts as one particle.','So the effective i falls below the ideal value. Dilute solutions come closer to 2.'],
    lab:{set:{view:'freeze',solute:'nacl',m:1,realI:true},look:'Read <b>van ’t Hoff factor used</b>.'}}
  ]},
bondtypes:{
  apNote:'Released questions from College Board. Solid-type questions link structure to melting point, conductivity and solubility.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'wires',kind:'real',lvl:'bio',
    q:'Phone chargers use copper wire covered in plastic. Why those two materials?',
    choices:['Copper is metallic and conducts; plastic is molecular and does not, so it keeps the current in the wire','Plastic conducts and copper insulates','Both conduct','Copper is cheaper than plastic'],correct:0,
    steps:['In copper, electrons are free to move through the metal.','In plastic, electrons are locked in covalent bonds inside each molecule.','So the copper carries the current and the plastic keeps it off your fingers.'],
    lab:{set:{sub:'Cu',setup:'solid'},look:'Watch the tester bulb, then try paraffin wax.'}},
  {id:'saltwater',kind:'test',lvl:'bio',
    q:'Solid salt does not conduct, but salt water does. Why?',
    choices:['Dissolving frees the ions so they can move','Water conducts by itself','Dissolving makes free electrons','The salt turns into metal'],correct:0,
    steps:['In the solid, Na⁺ and Cl⁻ ions are locked in place.','In water, they drift apart and move freely.','Moving charges carry current. Melted salt conducts for the same reason.'],
    lab:{set:{sub:'NaCl',setup:'water'},look:'Read <b>Tester bulb</b>.'}},
  {id:'sand',kind:'test',lvl:'bio',
    q:'Quartz sand (SiO₂) melts above 1600 °C, while wax melts near 58 °C. Why?',
    choices:['Every Si–O covalent bond in the network must break to melt sand; wax only needs weak forces between molecules overcome','Sand is heavier','Wax is ionic','Sand is a metal'],correct:0,
    steps:['Quartz is a network solid: one giant web of covalent bonds.','Paraffin is molecular: strong bonds inside each molecule, but weak attractions between them.','Melting wax only separates molecules, which is easy.'],
    lab:{set:{sub:'SiO2',setup:'heat',temp:1500},look:'Compare with paraffin wax at 100 °C.'}},
  {id:'classify',kind:'test',lvl:'honors',
    q:'A solid melts at 801 °C, dissolves in water, does not conduct as a solid but conducts as a liquid. What type is it?',
    choices:['Ionic','Molecular','Metallic','Network covalent'],correct:0,
    steps:['High melting point: strong forces throughout.','Conducts only when melted or dissolved: ions that become free to move.','Ionic. These are NaCl’s properties.']},
  {id:'graphite',kind:'test',lvl:'honors',
    q:'Pencil lead (graphite) conducts electricity even though it is all carbon. Why?',
    choices:['In each layer, every carbon shares one electron that is free to move along the layer','Graphite is ionic','Pencil lead is mostly metal','It does not conduct'],correct:0,
    steps:['Each carbon in graphite bonds to only 3 neighbors in a flat sheet.','The fourth electron spreads out across the whole sheet.','Those delocalized electrons carry current along the layers. Diamond, with all 4 bonded, does not conduct.'],
    lab:{set:{sub:'graphite',setup:'solid'},look:'Read <b>Tester bulb</b>.'}},
  {id:'alloy',kind:'ap',lvl:'ap',
    q:'Brass is copper with zinc atoms in place of some copper atoms. What kind of alloy is it, and why?',
    choices:['Substitutional, because Zn atoms are about the same size as Cu atoms','Interstitial, because Zn is small','Ionic','Network'],correct:0,
    steps:['Zn (about 134 pm) and Cu (about 128 pm) are close in size.','So Zn can take Cu’s place in the metal lattice.','Small atoms like carbon fit in the holes instead, making interstitial alloys like steel.'],
    lab:{set:{sub:'brass',setup:'solid'},look:'Compare the brass and steel pictures.'}}
  ]},
light:{
  apNote:'Released questions from College Board. Light questions use c = λν, E = hν and the photoelectric effect.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'sunburn',kind:'real',lvl:'bio',
    q:'You can sit under bright lamps all day without a sunburn, but 20 minutes of noon sun can burn you. Why?',
    choices:['UV photons carry enough energy each to damage DNA; visible photons do not, however many there are','The sun is brighter','Lamps are cooler','Sunburn comes from heat'],correct:0,
    steps:['Light comes in packets called photons. Shorter wavelength means more energy per photon.','A UV-B photon (300 nm) has more than twice the energy of a red one (700 nm), enough to break bonds in DNA.','More visible photons just means more of the same small packets. That is why sunscreen blocks UV.'],
    lab:{set:{pre:'uvb'},look:'Read <b>Energy per photon compared with red light</b>.'}},
  {id:'speed',kind:'test',lvl:'bio',
    q:'Which travels fastest through space: radio waves, visible light or X-rays?',
    choices:['They all travel at the same speed','X-rays','Radio waves','Visible light'],correct:0,
    steps:['All electromagnetic waves travel at c = 3.00 × 10⁸ m/s in a vacuum.','They differ in wavelength and frequency, not speed.','That is why a phone signal and the light from a screen reach you together.'],
    lab:{set:{pre:'fm'},look:'Compare the waves: different lengths, same speed.'}},
  {id:'freq',kind:'test',lvl:'honors',
    q:'A green laser has λ = 532 nm. What is its frequency? (c = 3.00 × 10⁸ m/s)',
    choices:['5.64 × 10¹⁴ Hz','1.77 × 10⁻¹⁵ Hz','5.64 × 10⁵ Hz','1.60 × 10¹¹ Hz'],correct:0,
    steps:['ν = c ÷ λ.','= 3.00 × 10⁸ ÷ 532 × 10⁻⁹ m.','= 5.64 × 10¹⁴ Hz.'],
    lab:{set:{pre:'grn'},look:'Read <b>Frequency</b>.'}},
  {id:'energy',kind:'test',lvl:'honors',
    q:'What is the energy of one photon of 532 nm light? (h = 6.626 × 10⁻³⁴ J·s)',
    choices:['3.74 × 10⁻¹⁹ J','3.74 × 10⁻¹⁵ J','1.17 × 10⁻²⁷ J','2.25 × 10⁵ J'],correct:0,
    steps:['E = hν, with ν = 5.64 × 10¹⁴ Hz.','= 6.626 × 10⁻³⁴ × 5.64 × 10¹⁴.','= 3.74 × 10⁻¹⁹ J, about 225 kJ per mole of photons.'],
    lab:{set:{pre:'grn'},look:'Read <b>Energy per photon E = hν</b>.'}},
  {id:'microwave',kind:'real',lvl:'honors',
    q:'Microwave ovens use 12.2 cm waves. Why can they heat food but not break chemical bonds?',
    choices:['Each microwave photon has far too little energy to break a bond, but many of them make water molecules spin and warm up','Microwaves have more energy than UV','Microwaves break every bond in food','They heat food with radioactivity'],correct:0,
    steps:['A 12.2 cm photon carries about 1/200 000 of the energy of a visible photon.','That is far below any bond energy, so no bonds break.','Instead, the oscillating field makes polar water molecules rotate back and forth, and that motion becomes heat.'],
    lab:{set:{pre:'mw'},look:'Read <b>Energy per photon compared with red light</b>.'}},
  {id:'photoel',kind:'ap',lvl:'ap',
    q:'Red light (650 nm, 1.91 eV per photon) shines on sodium (φ = 2.36 eV). What happens?',
    choices:['No electrons come out, however bright the light','A few electrons come out slowly','Many electrons come out','Electrons come out only if it is bright'],correct:0,
    steps:['One photon gives its energy to one electron.','1.91 eV is less than the 2.36 eV needed to free an electron from sodium.','Brightness adds more photons, not more energy per photon. Einstein’s explanation of this won the 1921 Nobel Prize.'],
    lab:{set:{target:'metal',metal:'na',pre:'red',bright:100},look:'Read <b>Electrons ejected</b>.'}}
  ]},
spectra:{
  apNote:'Released questions from College Board. Spectra questions connect line colors to electron energy levels and photon energy.',
  ap:[{title:'AP Chemistry exam page',url:'https://apcentral.collegeboard.org/courses/ap-chemistry/exam',note:'Exam format and past free-response questions.'}],
  questions:[
  {id:'fireworks',kind:'real',lvl:'bio',
    q:'Fourth of July fireworks get their red from strontium and their green from barium. Why do different metals give different colors?',
    choices:['Each element’s electrons have their own energy levels, so they give off light of their own wavelengths','The metals burn at different temperatures','The colors are painted on','All metals make every color'],correct:0,
    steps:['Heat kicks electrons up to higher energy levels.','When they fall back, each drop releases a photon whose energy matches the gap.','Every element has a different set of gaps, so a different set of colors: its fingerprint.'],
    lab:{set:{mode:'flame',salt:'sr'},look:'Read <b>Flame color</b> and <b>Brightest line</b>, then try barium.'}},
  {id:'lines',kind:'test',lvl:'bio',
    q:'Why does glowing hydrogen give only a few sharp colored lines instead of a full rainbow?',
    choices:['Electrons can only be at certain energy levels, so only certain energy drops are possible','Hydrogen is too small to make light','The spectroscope blocks the other colors','Hydrogen gives off only white light'],correct:0,
    steps:['Electron energy in an atom is quantized: only certain levels exist.','Each line is one specific drop, like 3 → 2 (red, 656 nm).','A continuous rainbow would need every energy, which atoms don’t allow.'],
    lab:{set:{mode:'hydrogen',nhi:6},look:'Count the visible lines.'}},
  {id:'sodium',kind:'real',lvl:'bio',
    q:'Old orange street lights are sodium lamps. Through a spectroscope, what would you see?',
    choices:['One bright yellow-orange line near 589 nm','A full rainbow','Only red','Nothing'],correct:0,
    steps:['Sodium’s strongest drop releases light at 589 nm.','That is the yellow-orange color.','It is so pure in color that cars look gray under it: there is no red or blue light to reflect.'],
    lab:{set:{mode:'flame',salt:'na'},look:'Read <b>Brightest line</b>.'}},
  {id:'bigger',kind:'test',lvl:'honors',
    q:'Which drop in hydrogen releases the higher-energy photon: 3 → 2 or 5 → 2?',
    choices:['5 → 2 (434 nm, violet)','3 → 2 (656 nm, red)','They are the same'],correct:0,
    steps:['A bigger drop in energy means a higher-energy photon.','Level 5 is higher than level 3, so 5 → 2 is the bigger drop.','Higher energy means shorter wavelength: violet instead of red.'],
    lab:{set:{mode:'hydrogen',nhi:5},look:'Read the line energies and wavelengths.'}},
  {id:'unknown',kind:'test',lvl:'honors',
    q:'An unknown salt gives a red flame. Lithium and strontium both do. What should you do?',
    choices:['Compare its spectroscope lines with lithium’s and strontium’s','Decide by how bright it is','Taste it','You cannot tell them apart'],correct:0,
    steps:['Two red flames can still have different line patterns.','Lithium’s brightest line is at 671 nm; strontium has several lines, some orange.','Matching the lines identifies the element.'],
    lab:{set:{mode:'flame',salt:'unk'},look:'Compare the unknown’s lines with lithium and strontium.'}},
  {id:'rydberg',kind:'ap',lvl:'ap',
    q:'What is the wavelength of the photon from n = 4 → n = 2 in hydrogen? ΔE = 2.178 × 10⁻¹⁸ J (1/n₁² − 1/n₂²).',
    num:{ans:486,tol:2,unit:'nm'},
    steps:['ΔE = 2.178 × 10⁻¹⁸ (1/4 − 1/16) = 2.178 × 10⁻¹⁸ × 0.1875 = 4.08 × 10⁻¹⁹ J.','λ = hc ÷ ΔE = (6.626 × 10⁻³⁴ × 3.00 × 10⁸) ÷ 4.08 × 10⁻¹⁹.','= 4.87 × 10⁻⁷ m ≈ 486 nm, the blue-green line.'],
    lab:{set:{mode:'hydrogen',nhi:4},look:'Find the 4 → 2 line.'}}
  ]}
});
